import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 15 lab — Polish, secure, record, rehearse","description":"","frontmatter":{"source":"weeks/15-ship-it/lab.md"},"headers":[],"relativePath":"weeks/15-ship-it/lab.md","filePath":"weeks/15-ship-it/lab.md"}'),i={name:"weeks/15-ship-it/lab.md"};function n(r,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="week-15-lab--polish-secure-record-rehearse" tabindex="-1">Week 15 lab — Polish, secure, record, rehearse <a class="header-anchor" href="#week-15-lab--polish-secure-record-rehearse" aria-label="Permalink to &quot;Week 15 lab — Polish, secure, record, rehearse&quot;">​</a></h1><blockquote><p>Two studios. <strong>Studio A:</strong> a polish sprint on your capstone: the empty, loading and error states, phone width, title and favicon, and accessibility, including one fix you write by hand. <strong>Studio B:</strong> an honest Known issues section, a final security pass, a 2–3 minute demo video and a rehearsal of your Project Fair pitch. Do the <strong>Core</strong> parts first. <strong>If time</strong> parts are optional. Work in the <a href="./../../resources/safe-loop.html">Safe Loop</a>: check first, small step, test, read the diff, teach back, commit.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely, in the Safe Loop · 🟡 AI limited: the AI may explain and critique, but you decide and write · 🔴 AI off: no AI tools at all, including code completions.</p><p><strong>What you need:</strong> your deployed capstone and its <strong>production URL</strong>, the <a href="./polish-checklist.html">Polish checklist</a>, the <a href="./../16-project-fair/project-fair.html">Project Fair guide</a> (for the feedback card) and a free built-in screen recorder (Part B3).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>No exit ticket and no oral walkthrough this week.</strong> University Regulation H-1-a doesn&#39;t allow quizzes or exams in class during the week before finals. Both studios are build time.</p></div><hr><h2 id="studio-a--polish-sprint-75-min" tabindex="-1">Studio A — Polish sprint (75 min) <a class="header-anchor" href="#studio-a--polish-sprint-75-min" aria-label="Permalink to &quot;Studio A — Polish sprint (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:30</td><td>Recap, concept talk and live demo, with your instructor</td><td></td></tr><tr><td>0:30–0:35</td><td><a href="#part-a1--set-up-the-sprint-core-5-min">Part A1 — Set up the sprint</a></td><td>Core, 5 min</td></tr><tr><td>0:35–0:55</td><td><a href="#part-a2--the-three-states-phone-title-and-favicon-core-20-min">Part A2 — The three states, phone, title and favicon</a></td><td>Core, 20 min</td></tr><tr><td>0:55–1:10</td><td><a href="#part-a3--accessibility-and-the-keyboard-test-core-15-min">Part A3 — Accessibility and the keyboard test</a></td><td>Core, 15 min</td></tr><tr><td>1:10–1:15</td><td>Checkpoint share: one thing the keyboard test or the three states showed you</td><td></td></tr><tr><td>Any spare minutes</td><td><a href="#part-a4--content-and-copy-if-time-10-min">Part A4 — Content and copy</a></td><td>If time, 10 min</td></tr></tbody></table><h3 id="part-a1--set-up-the-sprint-core-5-min" tabindex="-1">Part A1 — Set up the sprint (Core, 5 min) <a class="header-anchor" href="#part-a1--set-up-the-sprint-core-5-min" aria-label="Permalink to &quot;Part A1 — Set up the sprint (Core, 5 min)&quot;">​</a></h3><p>🟢 AI on for fixes, except the one in Part A2 that you write yourself. Work through the <a href="./polish-checklist.html">Polish checklist</a> against your <strong>live</strong> site. Fix the quick wins first. You won&#39;t finish every item: that&#39;s expected; the rest is homework.</p><ol><li><p>Open your <strong>production URL</strong> (not localhost) in a normal window, and again at phone width with your browser&#39;s device toolbar. The device toolbar is part of <a href="./../../resources/glossary.html#devtools">DevTools</a>, the browser&#39;s built-in developer tools (F12, or Cmd-Option-I on a Mac).</p></li><li><p>Work in this order: the <strong>three states</strong> (empty, loading, error) → <strong>phone</strong> → <strong>title and favicon</strong> → <strong>accessibility</strong>. The README and its Known issues section come in Studio B.</p></li><li><p>For each fix, write the &quot;done when&quot; check first. Where the fix is pure logic (choosing an empty-state message, formatting a date), the check is an automated test you write before the code and run with <code>npm test</code>. For layout, focus and wording, the check is a manual step you write in <code>TESTS.md</code>. Then prompt in the Safe Loop, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: While my saved notes load, show &quot;Loading your notes…&quot; and disable the Save button; if loading fails, show &quot;Couldn&#39;t load your notes. Check your connection and reload.&quot;</span></span>
<span class="line"><span>Context: public/app.js loads notes with fetch(&#39;/api/notes&#39;) in loadNotes() and writes them into &lt;ul id=&quot;notes&quot;&gt;. The starter&#39;s &quot;Ask the AI&quot; form in the same file already shows a message, disables its button, and uses try/catch/finally.</span></span>
<span class="line"><span>Constraints: Only change loadNotes() and style.css. Use textContent, not innerHTML. Don&#39;t change the server route.</span></span>
<span class="line"><span>Done when: With the network throttled I see the loading line; with the network offline I see the error line and the Save button works again; a normal load looks the same as before; npm test passes.</span></span></code></pre></div><p>Test every case yourself, read the diff (only the function you named should change), write a short teach-back in <code>PROMPTS.md</code>, and commit with an <code>Assisted-by:</code> line.</p></li></ol><h3 id="part-a2--the-three-states-phone-title-and-favicon-core-20-min" tabindex="-1">Part A2 — The three states, phone, title and favicon (Core, 20 min) <a class="header-anchor" href="#part-a2--the-three-states-phone-title-and-favicon-core-20-min" aria-label="Permalink to &quot;Part A2 — The three states, phone, title and favicon (Core, 20 min)&quot;">​</a></h3><p><strong>Trigger each state on purpose.</strong> Each should look intentional, with words that say what to do next.</p><ul><li><strong>Empty:</strong> open the app with no data. Sign in as a fresh test user, or delete your app&#39;s saved data (DevTools → <strong>Application</strong> → <strong>Local storage</strong>). Menus move: ask your assistant where it is in your browser.</li><li><strong>Loading:</strong> throttle the network (DevTools → <strong>Network</strong>, choose a slow preset) and reload.</li><li><strong>Error:</strong> set the same menu to <strong>Offline</strong>, or submit bad input.</li></ul><p><strong>Write the empty-state fix yourself (🔴 AI off, including completions).</strong> It&#39;s a small, real code change: find where the list is drawn, add a condition for &quot;no items&quot;, and show a helpful line such as &quot;No notes yet — add one above&quot; instead of a blank space. Check first: if the message comes from a <a href="./../../resources/glossary.html#pure-function">pure function</a> in <code>public/lib/</code> (like the starter&#39;s <code>summarize(items)</code> in <code>public/lib/items.js</code>), add a test for the empty case before you change it; otherwise write the manual check in <code>TESTS.md</code>. Commit it without an <code>Assisted-by:</code> line, and note it under &quot;What I wrote or decided myself&quot; in <code>PROMPTS.md</code>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>A Python habit to drop.</strong> In Python, <code>if not items:</code> is true for an empty list. In JavaScript an empty array <code>[]</code> is truthy, so <code>if (!items)</code> is false and the empty state never shows. Test <code>items.length === 0</code> instead (and use <code>===</code>: JavaScript&#39;s <code>==</code> converts types first, so <code>0 == &#39;&#39;</code> is true).</p></div><p><strong>Loading and error (🟢 AI on).</strong> Use a prompt like the one in Part A1. JavaScript&#39;s <code>try</code>/<code>catch</code>/<code>finally</code> works like Python&#39;s <code>try</code>/<code>except</code>/<code>finally</code>: put the line that hides &quot;Loading…&quot; or re-enables the button in <code>finally</code>, so it runs whether the request worked or failed.</p><p><strong>Phone.</strong> At phone width nothing scrolls sideways, buttons are big enough to tap, and text is readable without zooming. If the page looks zoomed out on a real phone, check <code>index.html</code> has the viewport tag from section 2 of the <a href="./polish-checklist.html">Polish checklist</a>.</p><p><strong>Title and favicon.</strong> The browser tab should name your app: the starter&#39;s says &quot;My Capstone&quot; until you change the <code>&lt;title&gt;</code> in <code>index.html</code>. Add a <a href="./../../resources/glossary.html#favicon">favicon</a>, the small icon in the tab: even a simple SVG works, with <code>&lt;link rel=&quot;icon&quot; href=&quot;favicon.svg&quot;&gt;</code> in the <code>&lt;head&gt;</code>.</p><p>✅ <strong>Checkpoint:</strong> you triggered all three states and each looks intentional, the app works at phone width, the tab shows a real title and a favicon, and your hand-written empty-state fix is committed. Check each one on the production URL after the deploy finishes.</p><h3 id="part-a3--accessibility-and-the-keyboard-test-core-15-min" tabindex="-1">Part A3 — Accessibility and the keyboard test (Core, 15 min) <a class="header-anchor" href="#part-a3--accessibility-and-the-keyboard-test-core-15-min" aria-label="Permalink to &quot;Part A3 — Accessibility and the keyboard test (Core, 15 min)&quot;">​</a></h3><p>🟢 AI on for finding problems and fixes. Two of the most common misses, and their fixes:</p><ul><li>An image with no <code>alt</code>: add <code>alt=&quot;Chart of weekly totals&quot;</code>, or <code>alt=&quot;&quot;</code> if it&#39;s purely decorative.</li><li>An input with no label: wrap it, for example <code>&lt;label&gt;Name &lt;input id=&quot;name&quot;&gt;&lt;/label&gt;</code>, or add <code>aria-label=&quot;Name&quot;</code>.</li></ul><p><strong>The keyboard test (do this one live).</strong> Put your mouse away. Press <strong>Tab</strong> through your whole app. You should be able to reach and use every button and field with Tab, Enter and Space, and always <strong>see</strong> where you are (a focus outline). If focus disappears, look in your CSS for <code>outline: none</code> and give focused elements a visible style instead, for example <code>:focus-visible { outline: 3px solid #1d4ed8; }</code>.</p><p>Then check that nothing important is shown by <strong>color alone</strong> (an error that only turns a box red): add words or an icon too.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Not sure about color contrast or missing labels? Your browser&#39;s built-in accessibility panel, or its Lighthouse audit, flags both. Menus move: ask your assistant where it is in your browser. If you use a screen reader yourself, the <a href="./../../resources/accessibility.html">Accessibility guide</a> covers the course&#39;s tools.</p></div><p>✅ <strong>Checkpoint:</strong> you tabbed through the entire app with no mouse and could see and use everything; every meaningful image has alt text and every input has a label. Commit after each fix.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>A fix broke another feature?</strong> You have a save point: <code>git restore [file]</code>, or revert the commit, and try a smaller step (the two-strikes rule). <strong>The live site looks different from localhost?</strong> The production URL is the one that&#39;s graded: push, wait for the deploy, and re-check. A <a href="./../../resources/glossary.html#hard-reload">hard reload</a> (Shift-reload) rules out an old cached copy.</p></div><h3 id="part-a4--content-and-copy-if-time-10-min" tabindex="-1">Part A4 — Content and copy (If time, 10 min) <a class="header-anchor" href="#part-a4--content-and-copy-if-time-10-min" aria-label="Permalink to &quot;Part A4 — Content and copy (If time, 10 min)&quot;">​</a></h3><p>Section 5 of the <a href="./polish-checklist.html">Polish checklist</a>: no leftover placeholder text (&quot;Lorem ipsum&quot;, &quot;TODO&quot;), buttons that say what they do (&quot;Save note&quot;, not &quot;Submit&quot;), numbers and dates formatted for a person, and spelling checked. Formatting is pure logic, so write the test first, for example that your formatter turns <code>1234.5</code> into <code>$1,234.50</code>. JavaScript&#39;s <code>Intl.NumberFormat</code> and <code>toLocaleDateString()</code> do most of the work. Dates have a trap that a test catches: <code>new Date(&#39;2026-12-14&#39;)</code> means midnight UTC, which is still December 13 in Idaho.</p><p><strong>Checkpoint share (5 min):</strong> two or three people say one thing the keyboard test or the three states showed them, and what they changed.</p><hr><h2 id="studio-b--ready-to-ship-75-min" tabindex="-1">Studio B — Ready to ship (75 min) <a class="header-anchor" href="#studio-b--ready-to-ship-75-min" aria-label="Permalink to &quot;Studio B — Ready to ship (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Show and tell: a polish fix, before and after</td><td></td></tr><tr><td>0:05–0:20</td><td><a href="#part-b1--readme-with-an-honest-known-issues-section-core-15-min">Part B1 — README with an honest Known issues section</a></td><td>Core, 15 min</td></tr><tr><td>0:20–0:35</td><td><a href="#part-b2--final-security-pass-core-15-min">Part B2 — Final security pass</a></td><td>Core, 15 min</td></tr><tr><td>0:35–0:40</td><td>Mini-lesson: tell the story, and a live recording demo, with your instructor</td><td></td></tr><tr><td>0:40–1:05</td><td><a href="#part-b3--record-your-demo-video-core-25-min">Part B3 — Record your demo video</a></td><td>Core, 25 min</td></tr><tr><td>1:05–1:15</td><td><a href="#part-b4--rehearse-your-fair-pitch-core-10-min">Part B4 — Rehearse your Fair pitch</a></td><td>Core, 10 min</td></tr><tr><td>After class</td><td><a href="#part-b5--final-submission-check-if-time-5-min">Part B5 — Final-submission check</a></td><td>If time, 5 min</td></tr></tbody></table><h3 id="part-b1--readme-with-an-honest-known-issues-section-core-15-min" tabindex="-1">Part B1 — README with an honest Known issues section (Core, 15 min) <a class="header-anchor" href="#part-b1--readme-with-an-honest-known-issues-section-core-15-min" aria-label="Permalink to &quot;Part B1 — README with an honest Known issues section (Core, 15 min)&quot;">​</a></h3><p>🟡 <strong>AI limited:</strong> you decide what&#39;s true; the AI may critique your wording. Open your README (from the <a href="./../../templates/PROJECT_README.html">README template</a>) and fill in <strong>Known issues</strong>. For each issue: what doesn&#39;t work, when it happens, any workaround, and what you&#39;d do next. For example:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Known issues</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Issue | When it happens | Workaround or plan |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Long notes overflow the card | Notes over about 300 characters, at phone width | Turn the phone sideways. Plan: let the text wrap in </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`.card\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (style.css) |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Everyone shares one list | Always: there&#39;s no sign-in in v1.0 (out of scope in SPEC.md) | Plan: Supabase Auth with per-user policies |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| The weather panel says &quot;unavailable&quot; | When the public weather API is down | Reload to retry |</span></span></code></pre></div><p>Use what you found in Studio A: the states you couldn&#39;t fix in time, the phone layout that still wraps oddly, the label you haven&#39;t added yet. Then put the bigger ideas under <strong>Next steps</strong>.</p><p>Naming a real limitation <strong>never costs points</strong>, and the Project Fair gives credit for it. Hiding one that a grader finds does.</p><p>✅ <strong>Checkpoint:</strong> your README lists at least one honest known issue, with when it happens and what you&#39;d do next, and it&#39;s committed. The rest of the README (section 6 of the <a href="./polish-checklist.html">Polish checklist</a>) is homework.</p><h3 id="part-b2--final-security-pass-core-15-min" tabindex="-1">Part B2 — Final security pass (Core, 15 min) <a class="header-anchor" href="#part-b2--final-security-pass-core-15-min" aria-label="Permalink to &quot;Part B2 — Final security pass (Core, 15 min)&quot;">​</a></h3><p>🟢 AI on for explaining results. Re-run the week 14 checks so nothing regressed while you polished.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:secrets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;innerHTML&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/</span></span></code></pre></div><p><code>npm run check:secrets</code> scans your files and your whole git history, so a clean result covers old commits too. Then, on the <strong>live</strong> site:</p><ul><li>Open DevTools → <strong>Sources</strong> and <strong>Network</strong>. Confirm no secret key is visible (only the project URL and publishable key, if you use Supabase).</li><li>Type <code>&lt;img src=x onerror=alert(1)&gt;</code> into every input, and reload if the app saves it. <strong>No alert</strong> should appear. If one does, that&#39;s <a href="./../../resources/glossary.html#xss">XSS</a>: find the <code>innerHTML</code> and switch to <code>textContent</code>.</li><li>If you have a database: <strong>Database → Advisors → Security</strong> shows no &quot;RLS Disabled&quot; error, and the check query at the end of <code>supabase/policies.sql</code> still matches your &quot;who may do what&quot; table from week 13.</li><li>In Vercel&#39;s project settings, confirm every secret is an environment variable there, and none is in your code.</li></ul><p>Update <a href="./../../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST.md template</a> with fresh evidence and today&#39;s date.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If a key turns up in your code, your history or the browser, fix that before you record anything. Revoke the key and make a new one first, then clean up (<a href="./../../resources/troubleshooting.html#i-committed-a-secret">Troubleshooting: I committed a secret</a>).</p></div><p>✅ <strong>Checkpoint:</strong> tests pass, no secrets found (including in history), the XSS payload stays inert, and RLS (if any) is on with the grants you intended.</p><p><strong>Mini-lesson (5 min):</strong> your instructor goes back to the story slide (problem → demo → how → what broke → what you learned) and records a short demo live with the built-in recorder, then shows how to add captions.</p><h3 id="part-b3--record-your-demo-video-core-25-min" tabindex="-1">Part B3 — Record your demo video (Core, 25 min) <a class="header-anchor" href="#part-b3--record-your-demo-video-core-25-min" aria-label="Permalink to &quot;Part B3 — Record your demo video (Core, 25 min)&quot;">​</a></h3><p>A 2–3 minute video so people can see your app even when it isn&#39;t running. Find a quiet corner if you&#39;ll speak.</p><p><strong>Free built-in recorders:</strong></p><ul><li><strong>macOS:</strong> press <strong>Shift-Cmd-5</strong>, choose to record the whole screen or a selected portion, then <strong>Record</strong>. Stop from the menu bar.</li><li><strong>Windows:</strong> <strong>Snipping Tool</strong> (it records video), or the <strong>Game Bar</strong> (<strong>Win-G</strong>, then record).</li><li><strong>ChromeOS:</strong> the <strong>Screen capture</strong> tool in quick settings, set to video.</li><li><strong>Any device:</strong> a phone camera pointed at the screen is acceptable for grading.</li></ul><p><strong>What to record (the story shape):</strong></p><ol><li><strong>Problem</strong> (about 15 seconds): who it&#39;s for and what it solves.</li><li><strong>Demo</strong> (60–90 seconds): do the main task live, including your feature types and <strong>one edge case</strong> handled well (empty input, an error).</li><li><strong>How</strong> (about 20 seconds): one line on how it&#39;s built and where the data and secrets live.</li><li><strong>What broke and what you learned</strong> (about 20 seconds): one honest moment.</li></ol><p><strong>Make it accessible.</strong> Add <strong>captions</strong> (automatic captions are fine once you&#39;ve fixed their mistakes) <strong>or a transcript</strong>. Writing your script first gives you the transcript for free. Put the transcript in your README under the video link, or upload it with the video.</p><p><strong>Can&#39;t record, or can&#39;t speak on a recording?</strong> Any of these counts the same: a silent recording with captions or on-screen text; a short sequence of screenshots with written narration; or a live 3-minute demo to your instructor, who notes it on Canvas. Ask early; the <a href="./../../resources/accessibility.html">Accessibility guide</a> explains how the course handles video.</p><p><strong>Privacy:</strong></p><ul><li>Close <code>.env</code>, terminals and dashboards before you start. <strong>Never show</strong> API keys, your Vercel or Supabase dashboards, or real people&#39;s information. Use made-up data.</li><li>Upload it as an <strong>unlisted</strong> video (only people with the link can watch) and put the link in your README and your Canvas submission. Rather not have your voice or face reachable from a public repo? Upload it to Canvas only and write &quot;Demo video: submitted on Canvas&quot; in the README.</li></ul><p><strong>Tips:</strong> rehearse once before you hit record; one clean take beats ten edited ones. If you fluff a line, keep going. Check the file plays and is under 3 minutes before you upload.</p><p>✅ <strong>Checkpoint:</strong> a 2–3 minute video exists, plays and shows no secrets. Captions or a transcript, the upload and the README link can be finished in the homework.</p><h3 id="part-b4--rehearse-your-fair-pitch-core-10-min" tabindex="-1">Part B4 — Rehearse your Fair pitch (Core, 10 min) <a class="header-anchor" href="#part-b4--rehearse-your-fair-pitch-core-10-min" aria-label="Permalink to &quot;Part B4 — Rehearse your Fair pitch (Core, 10 min)&quot;">​</a></h3><p>Pair up. Each of you gives your 60–90 second Fair pitch (problem → quick demo → one thing you&#39;re proud of → one known issue) and hands your partner the app at its production URL. Your partner tries it, fills in a <a href="./../16-project-fair/project-fair.html">feedback card</a> (🔴 AI off), and says one thing that landed and one thing to tighten. Swap.</p><p><strong>Working alone?</strong> Record your pitch, watch it back, and fill in the feedback card yourself (<a href="./../../resources/self-paced.html">Self-paced path</a>).</p><p>✅ <strong>Checkpoint:</strong> you&#39;ve said your pitch out loud once and have one concrete note to apply before the Fair.</p><h3 id="part-b5--final-submission-check-if-time-5-min" tabindex="-1">Part B5 — Final-submission check (If time, 5 min) <a class="header-anchor" href="#part-b5--final-submission-check-if-time-5-min" aria-label="Permalink to &quot;Part B5 — Final-submission check (If time, 5 min)&quot;">​</a></h3><p>Open the final submission checklist on the <a href="./../16-project-fair/">week 16 page</a>. Tick what&#39;s already done, and write down the one or two things that are left and when you&#39;ll do them. This is your plan, not a quiz: nobody collects it.</p><hr><h2 id="wrap-up" tabindex="-1">Wrap up <a class="header-anchor" href="#wrap-up" aria-label="Permalink to &quot;Wrap up&quot;">​</a></h2><ul><li>Commit all polish changes, the Known issues section and the updated <code>SECURITY_CHECKLIST.md</code>.</li><li>Make sure your README has the production URL, a screenshot and the demo video link (or &quot;submitted on Canvas&quot;).</li><li>Finish the rest of the <a href="./polish-checklist.html">Polish checklist</a> and the <a href="./homework.html">homework</a> before the Project Fair.</li><li>The Fair is in finals week, in the course&#39;s scheduled final exam slot (the day, time and room are on Canvas). Open your Supabase project the day before so it isn&#39;t paused.</li><li>Missed walkthrough 3 in week 14 for illness or another recognized reason? Tell your instructor: it&#39;s rescheduled without penalty, outside this week&#39;s studios (<a href="./../../assessment/oral-walkthroughs.html#what-to-expect">what to expect</a>).</li></ul>`,70)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
